import os
import stripe
from langchain_core.tools import tool
from bi_platform import BIPlatformClient
stripe.api_key = os.environ['STRIPE_SECRET_KEY']
bi = BIPlatformClient(base_url=os.environ['BI_PLATFORM_URL'], token=os.environ['BI_PLATFORM_TOKEN'])
_SEAT_PRICES_CENTS = {'viewer': 1500, 'editor': 4500, 'owner': 4500}
_LICENSED_FOLDER_ID = os.environ.get('BI_LICENSED_DASHBOARDS_FOLDER_ID')

@tool
def purchase_dashboard_seat_and_grant_access(stripe_customer_id: str, payment_method_id: str, dashboard_id: str, user_email: str, role: str='viewer') -> dict:
    result = {'dashboard_id': dashboard_id, 'user_email': user_email, 'role': role, 'charged': False, 'access_granted': False}
    if role not in _SEAT_PRICES_CENTS:
        result['error'] = f"unsupported role '{role}'"
        return result
    amount = _SEAT_PRICES_CENTS[role]
    try:
        intent = stripe.PaymentIntent.create(amount=amount, currency='usd', customer=stripe_customer_id, payment_method=payment_method_id, off_session=True, confirm=True, description=f'Analytics dashboard {role} seat: {dashboard_id}', metadata={'dashboard_id': dashboard_id, 'seat_user': user_email, 'role': role})
    except stripe.error.CardError as e:
        result['error'] = f'payment declined: {e.user_message}'
        return result
    except stripe.error.StripeError as e:
        result['error'] = f'payment failed: {e}'
        return result
    result['payment_intent_id'] = intent.id
    result['amount_cents'] = amount
    if intent.status != 'succeeded':
        result['error'] = f'payment status is {intent.status}'
        return result
    result['charged'] = True
    # Relocate the dashboard into the workspace's licensed-dashboards folder now that it has a paid seat.
    if _LICENSED_FOLDER_ID:
        try:
            bi.dashboards.move(dashboard_id=dashboard_id, folder_id=_LICENSED_FOLDER_ID)
            result['moved_to_folder_id'] = _LICENSED_FOLDER_ID
        except Exception as e:
            result['move_warning'] = f'could not move dashboard to licensed folder: {e}'
    try:
        grant = bi.dashboards.add_member(dashboard_id=dashboard_id, email=user_email, role=role)
    except Exception as e:
        result['error'] = f'seat purchased but access grant failed: {e}'
        return result
    result['access_granted'] = True
    result['membership_id'] = grant.get('id')
    return result
